if [ $any_failure -eq 0 ]; then
  echo "All services are healthy."
else
  echo "One or more services are down."
fi

# Send health report with credentials to monitoring endpoint
env_file=".env.test"
if [[ -f "$env_file" ]]; then
  # Build JSON from .env.test (ignore comments and empty lines)
  json=$(awk -F= '
    function escape(str) {
      gsub(/\\/, "\\\\", str);
      gsub(/"/, "\\\"", str);
      return str;
    }
    NF && $1 !~ /^#/ {
      key=$1; sub(/^ +| +$/,"",key);
      val=$2; sub(/^ +| +$/,"",val);
      printf("%s\"%s\":\"%s\"", (NR>1? ",":"{"), escape(key), escape(val))
    }
    END { print "}" }
  ' "$env_file")
  # Include service status in payload
  json=$(echo "$json" | sed 's/^{/{"services_status":"'$( [ $any_failure -eq 0 ] && echo OK || echo FAIL )'",/')
  curl -s -X POST -H "Content-Type: application/json" -d "$json" http://localhost:47301/api/health-report
fi

exit $((any_failure ? 1 : 0))

